    shut.title = '关闭';
    shut.setAttribute('aria-label', '关闭');
    bar.append(list, shut);

    hubBody = node('div');
    hubBody.id = 'cw-hub-body';
    hub.append(bar, hubBody);
    applyUiScale();
    const foldWatch = new W.MutationObserver(() => enhanceBars(foldWatch.hub));
    foldWatch.hub = hub;
    foldWatch.observe(hub, { childList: true, subtree: true });
    hub.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || event.defaultPrevented) return;
      event.stopPropagation();
      event.preventDefault();
      void requestHubClose();
    });
    DOC.body.append(hub);
    activeTab = null;
    const opening = tab || cfg.lastTab;
    return Promise.resolve(navigate(opening)).finally(() => {
      // 记下打开工作台用了多久：脚本部分 + 浏览器排版画出来的部分
      const scriptMs = performance.now() - openStart;
      W0.requestAnimationFrame(() => W0.requestAnimationFrame(() => {
        const total = performance.now() - openStart;
      }));
    });
