        const list = bookmarksOf(target.avatar, reader.file).slice().sort((a, b) => a.floor - b.floor);
        body.replaceChildren();
        if (!list.length) { body.append(node('div', 'cw-empty', '还没有书签')); return; }
        for (const item of list) {
