        version: 2,
        name: current,
        entries
      }, null, 2)],
      { type: 'application/json;charset=utf-8' }
    );

    const url = W.URL.createObjectURL(blob);
    const link = el('a');

    link.href = url;
    link.download = current + '_世界书快照.json';
    D.body.append(link);
    link.click();
    link.remove();

    W.setTimeout(() => W.URL.revokeObjectURL(url), 10000);
