          const tt=all?'整组关闭':'整组开启';if(tg.title!==tt){tg.title=tt;tg.setAttribute('aria-label',groups.label(g)+'：'+tt);}const ck=on===0?'false':all?'true':'mixed';if(tg.getAttribute('aria-checked')!==ck)tg.setAttribute('aria-checked',ck);
