/* ---------- 一栏一栏：点开在侧栏里往下展开，标题吸在顶上 ---------- */
const openSec = new Set(), secApis = new Map();
const reloadSec = key => { if (openSec.has(key)) { try { secApis.get(key)?.reload(); } catch {} } };
