  if (/\p{Script=Han}/u.test(ch)) {
    const bounds = '阿八嚓咑妸发旮哈丌咔垃妈拏噢妑七呥仨他屲夕丫帀', letters = 'ABCDEFGHJKLMNOPQRSTWXYZ';
