function safeSwitch() { const c = ctx(); return !(typeof c?.isGenerating === 'function' ? c.isGenerating() : c?.isGenerating) && !(c?.streamingProcessor && !c.streamingProcessor.isFinished && !c.streamingProcessor.isStopped); }
