    const get=TH('getWorldbook');if(!get)throw Error('需要新版酒馆助手世界书接口');
    const entries=await get(name);if(!valid(d.key))throw Error('存档已切换');
    if(!Array.isArray(entries))throw Error('世界书读取失败');
